/// <summary>
/// RV - 16/02/2022
/// Replication of Microsoft class <c>BankPaymAdviceCustDPTransferQueryGenerator</c> due to internal class declarations
/// with minor amendments to addInsertionFields() and addProjectionFields() to add required fields for Remittance advice.
/// </summary>
class METBankPaymAdviceCustDPTransferQueryGenerator
{
    METBankPaymAdviceCustTmp bankPaymAdviceCustTmp;

}

Method.Source:
    internal SysDaInsertObject createQuery(METBankPaymAdviceCustV2Tmp _bankPaymAdviceCustV2Tmp, guid _reportExecutionContext)
    {
        SysDaInsertObject insertObject = this.createInsertObject(_bankPaymAdviceCustV2Tmp);

        SysDaQueryObject queryObject = this.createQueryObject();
        this.addSelectionCriteria(queryObject, _reportExecutionContext);

        insertObject.query(queryObject);

        return insertObject;
    }

    private SysDaInsertObject createInsertObject(METBankPaymAdviceCustV2Tmp _bankPaymAdviceCustTmp)
    {
        SysDaInsertObject bankPaymAdviceCustTmpInsertObject = new SysDaInsertObject(_bankPaymAdviceCustTmp);
        this.addInsertionFields(bankPaymAdviceCustTmpInsertObject);

        return bankPaymAdviceCustTmpInsertObject;
    }

/// <summary>
/// Adds the <c>METBankPaymAdviceCustV2Tmp</c> table fields to an insert object.
/// </summary>
/// <param name = "_insertObject">
/// The insert object to add the fields.
/// </param>
protected void addInsertionFields(SysDaInsertObject _insertObject)
{
    _insertObject.fields()
        .add(fieldStr(METBankPaymAdviceCustV2Tmp, AccountNum))
        .add(fieldStr(METBankPaymAdviceCustV2Tmp,AmountCur ))
        .add(fieldStr(METBankPaymAdviceCustV2Tmp, Invoice))
        .add(fieldStr(METBankPaymAdviceCustV2Tmp, TransDate));
}

    private SysDaQueryObject createQueryObject()
    {
        SysDaQueryObject bankPaymAdviceCustTmpQueryObject = new SysDaQueryObject(bankPaymAdviceCustTmp);

        this.addProjectionFields(bankPaymAdviceCustTmpQueryObject);

        return bankPaymAdviceCustTmpQueryObject;
    }

/// <summary>
/// Adds <c>METBankPaymAdviceCustTmp</c> fields to the projection of a query object.
/// </summary>
/// <param name = "_queryObject">
/// The query object to add the fields.
/// </param>
protected void addProjectionFields(SysDaQueryObject _queryObject)
{
    _queryObject.projection()
       .add(fieldStr(METBankPaymAdviceCustTmp, AccountNum))
        .add(fieldStr(METBankPaymAdviceCustTmp,AmountCur ))
        .add(fieldStr(METBankPaymAdviceCustTmp, Invoice))
        .add(fieldStr(METBankPaymAdviceCustTmp, TransDate));
}

/// <summary>
/// Adds <c>METBankPaymAdviceCustTmp</c> fields to the query object where clause.
/// </summary>
/// <param name = "_queryObject">
/// The query object to add the fields
/// </param>
/// <param name = "_reportExecutionContext">
/// A unique execution guid used to distinguish between report executions.
/// </param>
protected void addSelectionCriteria(SysDaQueryObject _queryObject, guid _reportExecutionContext)
{
    _queryObject.whereClause(
        new SysDaEqualsExpression(
            new SysDaFieldExpression(bankPaymAdviceCustTmp, fieldStr(METBankPaymAdviceCustTmp, ExecutionContext)),
            new SysDaValueExpression(_reportExecutionContext)));
}

    /// <summary>
    /// Creates a SysDA query for the transfer of data between the <c>BankPaymAdviceVendTmp</c> physical table used by payment advice
    /// report generation and the <c>METBankPaymAdviceCustV2Tmp</c> temporary table used by the batchable report processing.
    /// </summary>
    /// <param name = "_bankPaymAdviceCustV2Tmp">
    /// The <c>METBankPaymAdviceVendV2Tmp</c> temporary table for insert.
    /// </param>
    /// <param name = "_reportExecutionContext">
    /// A unique execution guid used to distinguish between report executions.
    /// </param>
    /// <returns>
    /// A <c>SysDaInsertObject</c> object for transfer of data.
    /// </returns>
    internal static SysDaInsertObject newQuery(METBankPaymAdviceCustV2Tmp _bankPaymAdviceCustV2Tmp, guid _reportExecutionContext)
    {
        METBankPaymAdviceCustDPTransferQueryGenerator copyData = new METBankPaymAdviceCustDPTransferQueryGenerator();

        return copyData.createQuery(_bankPaymAdviceCustV2Tmp, _reportExecutionContext);
    }
